// Okay
let _ = a.rotate_right(u64::BITS);
// Panics (only when overflow checks are enabled)
let _ = a.funnel_shr(a, u64::BITS);
```

# u64::is_multiple_of

Kind: method
Defined in: `u64`
Signature: `pub const fn is_multiple_of(self, rhs: u64) -> bool`
Stable since: Rust 1.87.0

Returns `true` if `self` is an integer multiple of `rhs`, and false otherwise.

This function is equivalent to `self % rhs == 0`, except that it will not panic
for `rhs == 0`. Instead, `0.is_multiple_of(0) == true`, and for any non-zero `n`,
`n.is_multiple_of(0) == false`.

# Examples

```rust
assert!(6_u64.is_multiple_of(2));
assert!(!5_u64.is_multiple_of(2));

assert!(0_u64.is_multiple_of(0));
assert!(!6_u64.is_multiple_of(0));
```

